import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import { faBars } from "@fortawesome/free-solid-svg-icons";
import { useState } from "react";
export default function Topbar() {
  const [toggled, setToggled] = useState(false);
  return (
    <header
      className={` fixed z-[1] w-full flex items-center text-white
        ${"bg-black"}`}
      id="header"
    >
      <a className="cursor-pointer">
        <img className="m-4" src="/images/logo.png" alt="fitup logo" />
      </a>
      <nav>
        <ul className="ml-15 navigator hidden md:block">
          <li>
            <a href="#home">HOME</a>
          </li>
          <li>
            <a href="#aboutUs">ABOUT US</a>
          </li>
          <li>
            <a href="#services">SERVICES</a>
          </li>
          <li>
            <a href="#programs">PROGRAMS</a>
          </li>
          <li>
            <a href="#plans">PRICING</a>
          </li>
          <li>
            <a href="#contacts">CONTACTS</a>
          </li>
        </ul>
      </nav>
      <a
        href="/freetrial"
        className=" ml-[20%] md:ml-[40%] border-white border-2 px-4 py-2 cursor-pointer hover:bg-white hover:text-black"
      >
        Free trial
      </a>
      <button onClick={() => setToggled(true)}>
        <FontAwesomeIcon icon={faBars} />
      </button>
      {toggled && (
        <div className="bg-lick inset-0 fixed w-full h-[100vh] text-white">
          <h1 className="">TdIKSDJFIS</h1>

          <button onClick={() => setToggled(false)}>off</button>
        </div>
      )}
    </header>
  );
}
